# Medicine guides batch 2 (19 Nov 2026): heart and blood.
V, C, U, R, VR = ("v", "Very common", "more than 1 in 10"), ("c", "Common", "1 in 10 to 1 in 100"), ("u", "Uncommon", "1 in 100 to 1 in 1,000"), ("r", "Rare", "1 in 1,000 to 1 in 10,000"), ("vr", "Very rare", "fewer than 1 in 10,000")
def g(t, items): return (t[0], t[1], t[2], items)
PBS = "https://www.pbs.gov.au/pbs/search?term="
HF_BP = ("Heart Foundation: Hypertension guideline (2016)", "https://www.heartfoundation.org.au/for-professionals/hypertension")

med("calcium-channel-blockers", "Calcium Channel Blockers: Amlodipine, Felodipine, Diltiazem, Verapamil",
 "Calcium channel blockers explained: amlodipine, felodipine, lercanidipine, diltiazem and verapamil for blood pressure, angina and heart rhythm. Ankle swelling and other side effects.",
 "Calcium channel blockers", "Calcium channel blockers",
 [("m", "Blood pressure medicine"), ("l", "Prescription only (S4)")],
 "Some of the most prescribed blood pressure medicines in the world. They relax artery walls; some also slow the heart. Ankle swelling is the classic side effect.",
 "Calcium channel blockers lower blood pressure by relaxing the muscle in artery walls. Amlodipine, felodipine and lercanidipine mainly work on arteries and are first-line blood pressure medicines. Diltiazem and verapamil also slow the heart, so they’re used for angina and some fast heart rhythms.",
 [("For", "High blood pressure, angina; diltiazem and verapamil also for fast heart rhythms"),
  ("Works", "Lower systolic pressure by about 8 to 10 mmHg on average"),
  ("Cost", "PBS: $25 a script ($7.70 concession), often less than that"),
  ("Kicks in", "Full effect on blood pressure in 2 to 4 weeks"),
  ("Dose", "Amlodipine 2.5 to 10 mg once a day"),
  ("Watch for", "Ankle swelling, flushing, headache; constipation with verapamil")],
 "Quietly effective, once a day, and the main complaint is puffy ankles.",
 ["Amlodipine: Norvasc and generics. Felodipine: Plendil. Lercanidipine: Zanidip. Diltiazem: Cardizem, Vasocardol. Verapamil: Isoptin. Combinations with sartans or statins (e.g. Exforge, Caduet)"],
 "They block calcium from entering muscle cells in artery walls (and, for diltiazem and verapamil, the heart). Less calcium means the muscle relaxes, arteries widen and pressure falls.",
 ["High blood pressure (first-line choice, alone or with an ACE inhibitor or sartan)",
  "Angina",
  "Raynaud’s phenomenon (nifedipine, amlodipine, off label for some)",
  "Diltiazem and verapamil: slowing a fast heart rate in atrial fibrillation; verapamil for cluster headache prevention"],
 "Most people tolerate them well. Side effects often relate to widened blood vessels.",
 [g(V, ["<b>Ankle swelling</b> (amlodipine, especially at 10 mg)"]),
  g(C, ["Flushing", "Headache", "Dizziness", "Palpitations", "Tiredness", "Constipation (verapamil)"]),
  g(U, ["Gum overgrowth", "Slow heart rate (diltiazem, verapamil)"]),
  g(R, ["<b>Heart block</b> (diltiazem, verapamil)", "<b>Liver problems</b>"])],
 ["Fainting, very slow pulse or severe dizziness", "Chest pain that’s new or worse: call 000", "Yellow skin or eyes"],
 ["Grapefruit juice can raise levels of some (felodipine, nifedipine, verapamil).", "Diltiazem and verapamil interact with many medicines, including some statins; don’t combine them with beta-blockers without specialist advice.", "Ankle swelling doesn’t respond to diuretics; a lower dose or switching usually fixes it."],
 [("Why does amlodipine cause swollen ankles?", "It widens arteries more than veins, so fluid leaks from tiny vessels in the legs. It isn’t heart failure and water tablets don’t help much; a lower dose or another medicine can."),
  ("Is amlodipine a good blood pressure tablet?", "Yes. It’s one of the main first-line choices, taken once a day, and works well in older people and people of African or Asian descent."),
  ("Can I drink grapefruit juice with amlodipine?", "Amlodipine is only mildly affected; felodipine, nifedipine and verapamil are affected more. Check with your pharmacist.")],
 [HF_BP, ("PBS: Amlodipine", PBS + "amlodipine"), ("PBS: Diltiazem", PBS + "diltiazem")],
 [("High blood pressure", "/high-blood-pressure/"), ("Sartans (ARBs)", "/medicines/sartans/"), ("ACE inhibitors", "/medicines/ace-inhibitors/")])

med("sartans", "Sartans (ARBs): Candesartan, Irbesartan, Telmisartan, Losartan",
 "Sartans (angiotensin receptor blockers) explained: candesartan, irbesartan, telmisartan, losartan and others for blood pressure, heart failure and kidney protection. Side effects and blood tests.",
 "Sartans (ARBs)", "Sartans",
 [("m", "Blood pressure medicine"), ("l", "Prescription only (S4)")],
 "Blood pressure medicines that block the hormone angiotensin II. They protect the kidneys and heart, and unlike ACE inhibitors rarely cause a cough.",
 "Sartans (angiotensin II receptor blockers, ARBs) lower blood pressure and protect the kidneys in diabetes and kidney disease. They work like ACE inhibitors but further along the same pathway, so they almost never cause the dry cough. They need blood tests for kidney function and potassium.",
 [("For", "High blood pressure, heart failure, kidney protection in diabetes and kidney disease"),
  ("Works", "Lower blood pressure about as much as ACE inhibitors"),
  ("Cost", "PBS: $25 a script ($7.70 concession), often less than that"),
  ("Kicks in", "Full effect in 2 to 4 weeks"),
  ("Dose", "Once a day, e.g. candesartan 8 to 32 mg, irbesartan 150 to 300 mg"),
  ("Watch for", "Dizziness, high potassium, kidney changes; not in pregnancy")],
 "The ACE inhibitor without the cough.",
 ["Candesartan: Atacand. Irbesartan: Avapro, Karvea. Telmisartan: Micardis. Losartan: Cozaar. Olmesartan: Olmetec. Valsartan: Diovan. Many combinations with a diuretic or amlodipine"],
 "Angiotensin II tightens blood vessels and makes the body keep salt and water. Sartans block its receptor, so vessels relax, the kidneys release salt and pressure falls. They also reduce pressure inside the kidney’s filters, which slows kidney damage.",
 ["High blood pressure (first-line)",
  "Kidney protection when there’s protein in the urine, especially with diabetes",
  "Heart failure (candesartan, valsartan; valsartan also in sacubitril/valsartan, Entresto)",
  "An option when an ACE inhibitor causes a cough"],
 "Usually very well tolerated.",
 [g(C, ["Dizziness, especially at first", "<b>High potassium</b>", "Changes in kidney function on blood tests"]),
  g(U, ["Tiredness", "Low blood pressure"]),
  g(R, ["<b>Angioedema</b> (swelling of the face, lips or tongue), much rarer than with ACE inhibitors", "Severe diarrhoea and weight loss with olmesartan (sprue-like enteropathy)"])],
 ["Swelling of the lips, tongue or throat: call 000", "Fainting or very low blood pressure", "Weakness or an irregular heartbeat (possible high potassium)"],
 ["Not in pregnancy: stop and see your doctor if you’re planning pregnancy or become pregnant.", "Have kidney and potassium blood tests after starting and after dose changes.", "Avoid potassium supplements and salt substitutes containing potassium unless advised.", "‘Sick day rule’: pause it if you have vomiting, diarrhoea or can’t drink, then restart when well.", "Avoid regular anti-inflammatories (NSAIDs), especially with a diuretic too."],
 [("What is the difference between a sartan and an ACE inhibitor?", "Both block the same hormone pathway and lower blood pressure similarly. Sartans almost never cause the dry cough that ACE inhibitors can."),
  ("Do sartans protect the kidneys?", "Yes. In people with protein in the urine, especially with diabetes, they slow the decline in kidney function."),
  ("Can I take a sartan when pregnant?", "No. They can harm the baby’s kidneys. Talk to your doctor before pregnancy about switching.")],
 [HF_BP, ("PBS: Candesartan", PBS + "candesartan"), ("PBS: Irbesartan", PBS + "irbesartan")],
 [("ACE inhibitors", "/medicines/ace-inhibitors/"), ("High blood pressure", "/high-blood-pressure/"), ("Chronic kidney disease", "/chronic-kidney-disease/")])

med("diuretics", "Diuretics (Water Tablets): Furosemide, Hydrochlorothiazide, Spironolactone",
 "Diuretics (water tablets) explained: furosemide, hydrochlorothiazide, indapamide, chlortalidone and spironolactone for blood pressure, heart failure and swelling. Side effects and blood tests.",
 "Diuretics (water tablets)", "Diuretics",
 [("m", "Water tablet"), ("l", "Prescription only (S4)")],
 "Medicines that make the kidneys pass more salt and water. Used for blood pressure, heart failure and fluid build-up, and (spironolactone) acne and excess hair.",
 "Diuretics help the kidneys get rid of salt and water. Thiazide-type diuretics (indapamide, hydrochlorothiazide, chlortalidone) are long-acting blood pressure medicines. Loop diuretics (furosemide) are powerful and used for fluid build-up in heart failure. Spironolactone and eplerenone protect the heart in heart failure and help resistant blood pressure.",
 [("For", "High blood pressure, heart failure, fluid swelling, liver ascites; spironolactone for acne and hirsutism"),
  ("Works", "Thiazides lower pressure about 8 to 10 mmHg; spironolactone saves lives in heart failure"),
  ("Cost", "PBS: $25 a script ($7.70 concession), often less"),
  ("Kicks in", "Furosemide within an hour; thiazides over weeks for blood pressure"),
  ("Dose", "Usually in the morning to avoid night-time toilet trips"),
  ("Watch for", "Dehydration, low or high potassium, low sodium, gout")],
 "Cheap, old and still among the best-proven medicines in cardiology.",
 ["Furosemide: Lasix, Urex. Hydrochlorothiazide (in many combinations). Indapamide: Natrilix. Chlortalidone: Hygroton. Spironolactone: Aldactone. Eplerenone: Inspra"],
 "Each type blocks salt reabsorption in a different part of the kidney’s filtering tubes. Water follows the salt out. Spironolactone and eplerenone block aldosterone, a hormone that holds on to salt and scars the heart.",
 ["High blood pressure (thiazide-type)",
  "Heart failure: furosemide for swelling and breathlessness; spironolactone or eplerenone to protect the heart",
  "Fluid in the abdomen from liver disease (spironolactone with furosemide)",
  "Resistant high blood pressure (spironolactone)",
  "Off label: spironolactone for acne and excess hair in women"],
 "Side effects mostly come from shifts in salts and fluid. Regular blood tests catch most problems.",
 [g(V, ["Passing more urine"]),
  g(C, ["Dizziness, especially on standing", "<b>Low potassium</b> (furosemide, thiazides)", "<b>High potassium</b> (spironolactone, eplerenone)", "<b>Low sodium</b> (thiazides, especially in older people)", "Gout attacks", "Higher blood sugar", "Breast tenderness or growth (spironolactone)"]),
  g(U, ["Dehydration and kidney strain", "Erection problems", "Sun sensitivity"]),
  g(R, ["Hearing loss with high-dose IV furosemide", "<b>Pancreatitis</b>", "<b>Severe skin reactions</b>"])],
 ["Confusion, severe weakness or muscle cramps (salt imbalance)", "Fainting or very low blood pressure", "Passing very little urine"],
 ["Take in the morning (furosemide twice a day: morning and early afternoon).", "Blood tests for sodium, potassium and kidney function after starting and regularly.", "‘Sick day rule’: pause if you have vomiting, diarrhoea or can’t drink.", "Avoid regular anti-inflammatories (NSAIDs), especially with an ACE inhibitor or sartan.", "Hydrochlorothiazide used long term is linked to a slightly higher risk of non-melanoma skin cancer: use sun protection and check your skin."],
 [("When is the best time to take a water tablet?", "In the morning, so you’re not up at night to pass urine. With twice-daily furosemide, take the second dose by mid-afternoon."),
  ("Do diuretics cause gout?", "Thiazide and loop diuretics raise uric acid and can trigger gout. Your doctor may change medicine or add gout prevention."),
  ("Why is spironolactone used for acne?", "It blocks androgen hormones that drive oil production. It’s used off label in women with hormonal acne or excess hair.")],
 [HF_BP, ("PBS: Furosemide", PBS + "frusemide"), ("PBS: Spironolactone", PBS + "spironolactone")],
 [("High blood pressure", "/high-blood-pressure/"), ("Heart failure", "/heart-failure/"), ("Gout", "/gout/")])

med("blood-thinners", "Blood Thinners: Apixaban, Rivaroxaban, Dabigatran and Warfarin",
 "Blood thinners (anticoagulants) explained: apixaban, rivaroxaban, dabigatran and warfarin for atrial fibrillation, clots in the legs and lungs. Bleeding risk, INR tests, interactions and missed doses.",
 "Blood thinners (anticoagulants)", "Anticoagulants",
 [("l", "Anticoagulant"), ("l", "Prescription only (S4)")],
 "Medicines that slow blood clotting, to prevent strokes in atrial fibrillation and to treat or prevent clots in the legs and lungs. They save lives, at the cost of a higher bleeding risk.",
 "Anticoagulants reduce the blood’s ability to clot. The newer DOACs (apixaban, rivaroxaban, dabigatran) need no routine blood tests and have fewer interactions, so they’ve mostly replaced warfarin. Warfarin is still used for mechanical heart valves and some other conditions. In atrial fibrillation they cut stroke risk by about two-thirds.",
 [("For", "Atrial fibrillation, DVT and pulmonary embolism, clot prevention after hip and knee surgery, mechanical heart valves (warfarin)"),
  ("Works", "Reduce stroke risk in atrial fibrillation by about 60 to 70%"),
  ("Cost", "PBS: $25 a script ($7.70 concession)"),
  ("Kicks in", "DOACs within hours; warfarin takes days and needs INR tests"),
  ("Dose", "Apixaban usually 5 mg twice a day; rivaroxaban once a day with food"),
  ("Watch for", "Bleeding: black stools, blood in urine, large bruises, head injury")],
 "A small bleeding risk traded for a big stroke reduction. Usually a good deal.",
 ["Apixaban: Eliquis. Rivaroxaban: Xarelto. Dabigatran: Pradaxa. Warfarin: Coumadin, Marevan. Enoxaparin injections: Clexane"],
 "DOACs directly block one clotting factor (factor Xa for apixaban and rivaroxaban, thrombin for dabigatran). Warfarin blocks vitamin K recycling, lowering several clotting factors, which is why diet and many medicines change its effect.",
 ["Atrial fibrillation: stroke prevention, based on stroke risk (CHA2DS2-VA score)",
  "Treating deep vein thrombosis (DVT) and pulmonary embolism (PE)",
  "Preventing clots after hip and knee replacement",
  "Mechanical heart valves and some other conditions: warfarin only (DOACs don’t work well enough)"],
 "Bleeding is the main side effect. Most is minor (nosebleeds, bruising), but serious bleeding can happen.",
 [g(C, ["Bruising", "Nosebleeds and gum bleeding", "Heavier periods", "Indigestion (dabigatran)"]),
  g(U, ["<b>Stomach or bowel bleeding</b>", "Blood in the urine", "Anaemia"]),
  g(R, ["<b>Bleeding in the brain</b>", "Skin necrosis or purple toes (warfarin)"])],
 ["Any head injury, even minor: get checked the same day", "Black or bloody stools, vomiting blood, or coughing blood", "Sudden severe headache, weakness or trouble speaking: call 000", "Bleeding that won’t stop"],
 ["Take it at the same time every day; missing doses raises clot risk.", "Tell every doctor, dentist and pharmacist. Most dental work can go ahead without stopping.", "Avoid anti-inflammatories (NSAIDs) and aspirin unless your doctor says otherwise.", "Warfarin: keep green-vegetable intake steady, have regular INR tests, and check every new medicine or supplement.", "DOACs need lower doses in kidney disease; have kidney blood tests at least yearly.", "Reversal agents exist for dabigatran (idarucizumab) and warfarin (vitamin K)."],
 [("Which is better, apixaban or warfarin?", "For most people with atrial fibrillation, DOACs like apixaban are at least as good at preventing stroke with less brain bleeding, and need no INR tests. Warfarin is still needed for mechanical valves."),
  ("What if I miss a dose of apixaban?", "Take it as soon as you remember the same day, then carry on as normal. Don’t double up. Check the leaflet or your pharmacist for your specific medicine."),
  ("Can I drink alcohol on blood thinners?", "Small amounts are usually fine. Heavy drinking raises bleeding risk and makes warfarin unpredictable.")],
 [("Healthdirect: Blood thinners", "https://www.healthdirect.gov.au/blood-thinners"), ("PBS: Apixaban", PBS + "apixaban"), ("PBS: Warfarin", PBS + "warfarin")],
 [("Atrial fibrillation", "/atrial-fibrillation/"), ("Antiplatelets", "/medicines/antiplatelets/"), ("Stroke deep dive", "/deep-dives/stroke/")])

med("antiplatelets", "Antiplatelets: Aspirin, Clopidogrel, Ticagrelor and Prasugrel",
 "Antiplatelet medicines explained: low-dose aspirin, clopidogrel, ticagrelor and prasugrel after heart attacks, stents and strokes. Who should (and shouldn’t) take aspirin, bleeding risk and stopping before surgery.",
 "Antiplatelets", "Antiplatelets",
 [("m", "Antiplatelet"), ("s", "Aspirin OTC; others prescription")],
 "Medicines that stop platelets sticking together, to prevent heart attacks and strokes in people who’ve already had one or have a stent. No longer recommended for most healthy people.",
 "Antiplatelets make platelets less sticky, reducing clots in arteries. After a heart attack, stent or stroke they clearly prevent repeat events. For healthy people without heart disease, daily aspirin’s small benefit is cancelled out by bleeding risk, so it’s no longer routinely recommended for prevention.",
 [("For", "After heart attack, stents, angina, stroke and TIA, peripheral artery disease"),
  ("Works", "Lower repeat heart attack and stroke risk by about 20 to 25% after a first event"),
  ("Cost", "Aspirin a few dollars; others PBS $25 a script ($7.70 concession)"),
  ("Kicks in", "Within hours; effect lasts the life of the platelets (7 to 10 days)"),
  ("Dose", "Aspirin 100 mg daily; clopidogrel 75 mg daily"),
  ("Watch for", "Bleeding, bruising, indigestion")],
 "Essential after a heart attack. Not a daily vitamin for the healthy.",
 ["Aspirin: Cartia, Astrix, Cardiprin. Clopidogrel: Plavix, Iscover. Ticagrelor: Brilinta. Prasugrel: Effient. Aspirin with dipyridamole: Asasantin"],
 "Platelets plug damaged blood vessels. In narrowed arteries, they also trigger dangerous clots. Aspirin blocks platelets’ ability to make thromboxane; clopidogrel, ticagrelor and prasugrel block their P2Y12 receptor.",
 ["After a heart attack or stent: usually two antiplatelets (dual therapy) for 6 to 12 months, then one",
  "After an ischaemic stroke or TIA",
  "Stable angina and peripheral artery disease",
  "Not recommended for most healthy people to prevent a first heart attack",
  "Low-dose aspirin is used in pregnancy to prevent pre-eclampsia in high-risk women"],
 "Bleeding is the main risk, higher with two antiplatelets or with blood thinners.",
 [g(C, ["Bruising", "Nosebleeds", "Indigestion", "Breathlessness (ticagrelor)"]),
  g(U, ["<b>Stomach or bowel bleeding</b>", "Stomach ulcer (aspirin)"]),
  g(R, ["<b>Bleeding in the brain</b>", "Asthma attacks triggered by aspirin in some people", "Low platelets (TTP) with clopidogrel"])],
 ["Black or bloody stools or vomiting blood", "Sudden severe headache, weakness or trouble speaking: call 000", "Bleeding that won’t stop"],
 ["Never stop antiplatelets after a stent without talking to your cardiologist: early stopping can cause the stent to block.", "Tell your surgeon and dentist; most dental work can go ahead.", "Some people taking aspirin with another blood thinner need a stomach-protecting medicine (PPI).", "Omeprazole and esomeprazole may weaken clopidogrel slightly; pantoprazole is often preferred."],
 [("Should I take aspirin every day?", "If you’ve had a heart attack, stent or stroke, usually yes. If you’re healthy, guidelines no longer recommend it for most people because bleeding risk outweighs the small benefit."),
  ("Why two blood thinners after a stent?", "Dual antiplatelet therapy stops clots forming on the new stent while the artery heals, usually for 6 to 12 months."),
  ("Do I stop aspirin before surgery?", "Ask your surgeon. Aspirin is often continued, especially after a stent. Clopidogrel, ticagrelor and prasugrel are usually stopped 5 to 7 days before major surgery, but only on specialist advice.")],
 [("PBS: Clopidogrel", PBS + "clopidogrel"), ("PBS: Ticagrelor", PBS + "ticagrelor"), ("Heart Foundation: Heart attack medication", "https://www.heartfoundation.org.au/bundles/support/heart-attack-medication")],
 [("Blood thinners", "/medicines/blood-thinners/"), ("Statins", "/medicines/statins/"), ("Stroke deep dive", "/deep-dives/stroke/")])
